package vn.iotstar;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
import java.time.*;import java.util.*;
import vn.iotstar.config.*;import vn.iotstar.entity.*;import vn.iotstar.service.impl.AuthService;import vn.iotstar.security.PasswordHasher;
class AuthServiceIntegrationTest {
    static class Time extends Clock {Instant now=Instant.parse("2026-11-16T00:00:00Z");public java.time.ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(java.time.ZoneId zone){return this;}public Instant instant(){return now;}}
    Time time;List<String> codes;AuthService auth;
    @BeforeEach void init(){Db.write(em->{em.createQuery("DELETE FROM Video").executeUpdate();em.createQuery("DELETE FROM OtpToken").executeUpdate();em.createQuery("DELETE FROM AppUser").executeUpdate();return null;});time=new Time();codes=new ArrayList<>();auth=new AuthService((to,purpose,code)->codes.add(code),time);}
    @AfterAll static void close(){JpaConfig.close();}
    AppUser register(){return auth.register("tester","test@example.com","Người kiểm thử","StrongPass9!");}
    String latest(){return codes.get(codes.size()-1);}
    @Test void passwordUsesSaltAndVerification(){String one=PasswordHasher.hash("StrongPass9!"),two=PasswordHasher.hash("StrongPass9!");assertNotEquals(one,two);assertTrue(PasswordHasher.verify("StrongPass9!",one));assertFalse(PasswordHasher.verify("wrong",one));assertFalse(PasswordHasher.verify("StrongPass9!","broken"));}
    @Test void registrationIsInactiveUntilOtpActivation(){var u=register();assertFalse(auth.find(u.getId()).isActive());assertNotEquals("StrongPass9!",auth.find(u.getId()).getPasswordHash());assertThrows(IllegalArgumentException.class,()->auth.login("tester","StrongPass9!"));auth.activate("test@example.com",latest());assertTrue(auth.login("TESTER","StrongPass9!").isActive());assertThrows(IllegalArgumentException.class,()->auth.activate("test@example.com",latest()));}
    @Test void otpIsHashedAndBoundToPurpose(){register();String code=latest();String stored=Db.read(em->em.createQuery("SELECT t FROM OtpToken t",OtpToken.class).getSingleResult().getCodeHash());assertNotEquals(code,stored);assertTrue(PasswordHasher.verify(code,stored));assertThrows(IllegalArgumentException.class,()->auth.resetPassword("test@example.com",code,"Replacement9!"));}
    @Test void wrongOtpAttemptsPersistAndLock(){register();String correct=latest(),wrong=correct.equals("000000")?"111111":"000000";for(int i=0;i<5;i++)assertThrows(IllegalArgumentException.class,()->auth.activate("test@example.com",wrong));assertEquals(5,Db.read(em->em.createQuery("SELECT t FROM OtpToken t",OtpToken.class).getSingleResult().getAttempts()).intValue());assertThrows(IllegalArgumentException.class,()->auth.activate("test@example.com",correct));}
    @Test void expiredOtpCannotActivate(){register();String code=latest();time.now=time.now.plusSeconds(301);assertThrows(IllegalArgumentException.class,()->auth.activate("test@example.com",code));}
    @Test void resendThrottlesAndInvalidatesPreviousOtp(){register();String old=latest();assertThrows(IllegalArgumentException.class,()->auth.requestOtp("test@example.com","ACTIVATE"));time.now=time.now.plusSeconds(61);auth.requestOtp("test@example.com","ACTIVATE");String fresh=latest();assertNotEquals(old,fresh);assertThrows(IllegalArgumentException.class,()->auth.activate("test@example.com",old));auth.activate("test@example.com",fresh);}
    @Test void resetNeedsCorrectOtpAndInvalidatesSessions(){var u=register();auth.activate(u.getEmail(),latest());auth.requestOtp(u.getEmail(),"RESET");String reset=latest();assertThrows(IllegalArgumentException.class,()->auth.resetPassword(u.getEmail(),"bad","Replacement9!"));auth.resetPassword(u.getEmail(),reset,"Replacement9!");assertThrows(IllegalArgumentException.class,()->auth.login("tester","StrongPass9!"));assertEquals(1,auth.login(u.getEmail(),"Replacement9!").getSessionVersion());assertThrows(IllegalArgumentException.class,()->auth.resetPassword(u.getEmail(),reset,"AnotherPass9!"));}
    @Test void duplicateAndWeakInputsRejected(){register();assertThrows(IllegalArgumentException.class,()->register());assertThrows(IllegalArgumentException.class,()->auth.register("x","bad","Name","123"));}
    @Test void mailFailureRollsBackRegistration(){var failing=new AuthService((to,p,c)->{throw new IllegalStateException("SMTP down");},time);assertThrows(IllegalStateException.class,()->failing.register("tester","test@example.com","Test","StrongPass9!"));assertEquals(0L,Db.read(em->em.createQuery("SELECT COUNT(u) FROM AppUser u",Long.class).getSingleResult()).longValue());}
    @Test void repeatedWrongPasswordsTemporarilyLockAccount(){register();auth.activate("test@example.com",latest());for(int i=0;i<5;i++)assertThrows(IllegalArgumentException.class,()->auth.login("tester","bad"));assertThrows(IllegalArgumentException.class,()->auth.login("tester","StrongPass9!"));time.now=time.now.plusSeconds(901);assertNotNull(auth.login("tester","StrongPass9!"));}
}
